INSERT INTO `fp_methods` (`method_id`, `method_code`, `method_name`, `method_category`, `duration_months`, `hormonal`, `provider_administered`, `permanent`, `typical_use_note`, `effectiveness_note`, `clinical_note`) VALUES
(1, 'MCON', 'Male condom', 'Barrier', 0.03, 0, 0, 0, 'Use a new condom for every act of sex.', 'Contraception plus STI/HIV risk reduction when used correctly and consistently.', 'Single-use barrier method.'),
(2, 'FCON', 'Female/internal condom', 'Barrier', 0.03, 0, 0, 0, 'Insert before sex and use once.', 'User-controlled barrier option that can reduce STI/HIV transmission risk.', 'Single-use internal barrier method.'),
(3, 'COC', 'Combined oral contraceptive pill', 'Short-acting hormonal', 1.0, 1, 0, 0, 'Take one pill every day according to the pack schedule.', 'Reversible and effective with consistent daily use.', 'Requires clinical eligibility assessment.'),
(4, 'POP', 'Progestin-only pill', 'Short-acting hormonal', 1.0, 1, 0, 0, 'Take one pill every day on a regular schedule.', 'Reversible estrogen-free oral option.', 'Follow product-specific missed-pill guidance.'),
(5, 'DMPA', 'DMPA injectable', 'Injectable', 3.0, 1, 1, 0, 'Receive injection at recommended intervals.', 'Several months of protection per dose; no daily action.', 'Repeat on schedule according to current guidance.'),
(6, 'NETEN', 'NET-EN injectable', 'Injectable', 2.0, 1, 1, 0, 'Receive injection at recommended intervals.', 'Reversible and discreet.', 'Repeat injections are required.'),
(7, 'IMP3', '3-year contraceptive implant', 'Implant', 36.0, 1, 1, 0, 'Inserted under upper-arm skin by a trained provider.', 'Highly effective, long-acting and reversible.', 'Requires trained insertion and removal.'),
(8, 'IMP5', '5-year contraceptive implant', 'Implant', 60.0, 1, 1, 0, 'Inserted under upper-arm skin by a trained provider.', 'Highly effective, long-acting and reversible.', 'Requires trained insertion and removal.'),
(9, 'CUIUD', 'Copper IUD', 'Intrauterine', 120.0, 0, 1, 0, 'Inserted into the uterus by a trained provider.', 'Very long-acting, reversible and hormone-free.', 'Requires trained insertion and removal.'),
(10, 'LNGIUS', 'Levonorgestrel intrauterine system', 'Intrauterine', 60.0, 1, 1, 0, 'Inserted into the uterus by a trained provider.', 'Long-acting and reversible; may reduce menstrual bleeding.', 'Requires trained insertion and removal.'),
(11, 'EC', 'Emergency contraceptive pill', 'Emergency', 0.03, 1, 0, 0, 'Take after unprotected sex as soon as possible within the recommended window.', 'Backup after unprotected sex or contraceptive failure.', 'Not intended as a regular ongoing method.'),
(12, 'LAM', 'Lactational amenorrhea method', 'Fertility awareness', 6.0, 0, 0, 0, 'Use only when all LAM eligibility criteria are met.', 'No medicine or device required.', 'Time-limited postpartum method.'),
(13, 'FAM', 'Fertility awareness methods', 'Fertility awareness', 1.0, 0, 0, 0, 'Track fertility signs/cycle timing and avoid unprotected sex during fertile days.', 'Non-hormonal and user-controlled.', 'Requires consistent tracking.'),
(14, 'TL', 'Female sterilization/tubal ligation', 'Permanent', NULL, 0, 1, 1, 'Performed surgically by a qualified provider after informed consent.', 'Highly effective permanent contraception.', 'Permanent method requiring counselling and clinical assessment.');
