INSERT INTO `fp_method_cautions` (`caution_id`, `method_id`, `caution_text`) VALUES
(1, 1, 'Do not reuse.'),
(2, 2, 'Do not use an internal and external condom together.'),
(3, 3, 'Estrogen-containing methods are not suitable for everyone; assess eligibility.'),
(4, 4, 'Timing and adherence matter; follow current guidance.'),
(5, 5, 'Repeat dosing should follow current national guidance.'),
(6, 6, 'Repeat injections are required on schedule.'),
(7, 7, 'Insertion/removal require a trained provider.'),
